"use strict";(function(){const e=document.querySelector(".jw-primary-nav");if(!e)return;e.addEventListener("click",e=>{const s=e.target.closest(".jw-section summary");if(!s||e.target.closest("a"))return;const t=s.parentElement;if(!t||!t.matches("details"))return;if(e.preventDefault(),!t.open){t.open=!0,t.classList.add("is-collapsing"),requestAnimationFrame(()=>t.classList.remove("is-collapsing"));return}const n=t.querySelector(":scope > .jw-nav-branch");if(window.matchMedia("(prefers-reduced-motion: reduce)").matches||!n){t.open=!1;return}t.classList.add("is-collapsing"),n.addEventListener("transitionend",function e(s){if(s.propertyName!=="grid-template-rows")return;n.removeEventListener("transitionend",e),t.open=!1,t.classList.remove("is-collapsing")})})})()